INSERT INTO "events" ("id", "title", "date", "location", "banner_url", "description", "created_at") VALUES ('a4ad2e26-15b2-4cd7-ad81-51a944592672', 'AI-Powered Business Automation Workshop', '2025-10-15', 'Tech Innovation Center, San Francisco', 'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=800&h=400&fit=crop&crop=center', 'Join us for an intensive hands-on workshop where you''ll learn how to implement AI-driven automation solutions in your business. We''ll cover process optimization, intelligent workflows, and ROI measurement strategies. Perfect for business leaders and technical teams looking to streamline operations.', '2025-09-23 16:53:44.835627+00');
INSERT INTO "events" ("id", "title", "date", "location", "banner_url", "description", "created_at") VALUES ('15c53cdc-4df0-47e3-8f11-bf3183755474', 'Machine Learning for Customer Intelligence Summit', '2025-10-28', 'Convention Center, New York', 'https://images.unsplash.com/photo-1531482615713-2afd69097998?w=800&h=400&fit=crop&crop=center', 'Discover how leading companies are using machine learning to understand customer behavior, predict trends, and drive personalized experiences. Features keynotes from industry experts, case studies, and networking opportunities.', '2025-09-23 16:53:45.222324+00');
INSERT INTO "events" ("id", "title", "date", "location", "banner_url", "description", "created_at") VALUES ('e86a309f-5da7-4e00-b343-bb006ca397ff', 'Future of AI in Healthcare Symposium', '2025-11-12', 'Medical Research Institute, Boston', 'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?w=800&h=400&fit=crop&crop=center', 'Explore cutting-edge AI applications in healthcare, from diagnostic imaging to drug discovery. Learn about regulatory compliance, ethical considerations, and implementation strategies from healthcare AI pioneers.', '2025-09-23 16:53:45.341098+00');
INSERT INTO "events" ("id", "title", "date", "location", "banner_url", "description", "created_at") VALUES ('4038bc75-9210-4f21-a2b8-60d73eaace52', 'AI Ethics and Responsible Innovation Panel', '2025-11-25', 'University Campus, Seattle', 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?w=800&h=400&fit=crop&crop=center', 'A thought-provoking discussion on the ethical implications of AI development and deployment. Join leading ethicists, technologists, and policymakers as they explore frameworks for responsible AI innovation.', '2025-09-23 16:53:45.436665+00');
INSERT INTO "events" ("id", "title", "date", "location", "banner_url", "description", "created_at") VALUES ('b8c25850-5ee7-4152-86e9-6639ee8339b7', 'Generative AI for Creative Industries Masterclass', '2025-12-08', 'Creative Hub, Los Angeles', 'https://images.unsplash.com/photo-1552664730-d307ca884978?w=800&h=400&fit=crop&crop=center', 'Learn how generative AI is revolutionizing creative workflows in design, marketing, and content creation. Hands-on sessions with the latest AI tools and techniques for creative professionals.', '2025-09-23 16:53:45.528189+00');
INSERT INTO "events" ("id", "title", "date", "location", "banner_url", "description", "created_at") VALUES ('1b09baa3-4d4b-4dbc-aa0d-e191cd301d2e', 'AI-Driven Financial Analytics Conference', '2025-12-20', 'Financial District, Chicago', 'https://images.unsplash.com/photo-1559136555-9303baea8ebd?w=800&h=400&fit=crop&crop=center', 'Discover how artificial intelligence is transforming financial services through advanced analytics, risk assessment, and automated trading strategies. Network with fintech innovators and AI specialists.', '2025-09-23 16:53:45.622342+00');
