INSERT INTO "solutions" ("id", "title", "description", "short_description", "category", "features", "benefits", "use_cases", "pricing", "image_url", "icon_name", "status", "featured", "sort_order", "created_at", "updated_at") VALUES ('d7a2e721-7bf7-4ead-9356-e291e5e01aa5', 'AI Analytics Services', 'Transform your business intelligence with our advanced AI analytics platform. Our solution provides real-time insights, predictive analytics, and automated reporting that helps businesses make data-driven decisions faster than ever before.', 'Advanced AI-powered analytics for real-time business insights and predictive reporting', 'Analytics Services', Real-time data processing,Predictive modeling,Automated reporting,Custom dashboard creation,Machine learning algorithms,Data visualization tools, 40% faster decision making,Reduced manual reporting time,Improved accuracy in forecasting,Cost-effective data analysis, Sales forecasting,Customer behavior analysis,Market trend prediction,Performance optimization,Risk assessment, 'Starting at $299/month', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=600&h=400&fit=crop&crop=center', 'BarChart3', 'published', true, 1, '2025-09-27 04:00:52.364062+00', '2025-09-27 04:00:52.364062+00');
INSERT INTO "solutions" ("id", "title", "description", "short_description", "category", "features", "benefits", "use_cases", "pricing", "image_url", "icon_name", "status", "featured", "sort_order", "created_at", "updated_at") VALUES ('a46b5ab6-acab-42ff-b31d-25735f300798', 'Data Cleaning & Processing', 'Streamline your data pipeline with our intelligent data cleaning and processing solutions. Our AI-powered platform automatically identifies and corrects data inconsistencies, handles missing values, and prepares your data for analysis.', 'Automated data cleaning and processing with AI-powered quality assurance', 'Data Processing', Automated data validation,Missing value imputation,Duplicate detection,Data transformation,Quality scoring,Real-time monitoring, 90% reduction in data errors,Automated quality checks,Faster data preparation,Consistent data standards, Customer database cleaning,Sales data processing,Inventory management,Financial data validation, 'Starting at $199/month', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=600&h=400&fit=crop&crop=center', 'Database', 'published', false, 2, '2025-09-27 04:00:52.817619+00', '2025-09-27 04:00:52.817619+00');
INSERT INTO "solutions" ("id", "title", "description", "short_description", "category", "features", "benefits", "use_cases", "pricing", "image_url", "icon_name", "status", "featured", "sort_order", "created_at", "updated_at") VALUES ('f00eba16-1214-488c-881f-352f23a2562e', 'AI Agent Development', 'Build intelligent AI agents that can handle complex business processes, customer interactions, and automated workflows. Our platform provides everything you need to create, train, and deploy sophisticated AI agents.', 'Custom AI agents for business process automation and customer interaction', 'AI Agent Development', Natural language processing,Multi-channel deployment,Learning capabilities,Integration APIs,Custom training models,Performance analytics, 24/7 automated support,Scalable customer service,Reduced operational costs,Improved response times, Customer support bots,Sales assistance agents,Internal process automation,Lead qualification, 'Starting at $399/month', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=600&h=400&fit=crop&crop=center', 'Bot', 'published', true, 3, '2025-09-27 04:00:52.986603+00', '2025-09-27 04:00:52.986603+00');
INSERT INTO "solutions" ("id", "title", "description", "short_description", "category", "features", "benefits", "use_cases", "pricing", "image_url", "icon_name", "status", "featured", "sort_order", "created_at", "updated_at") VALUES ('ce26e060-3d30-4258-9f32-a7ac9e6e6b5f', 'Machine Learning Models', 'Deploy custom machine learning models tailored to your business needs. Our platform supports various ML algorithms and provides tools for model training, validation, and deployment in production environments.', 'Custom machine learning models for predictive analytics and automation', 'Machine Learning', Multiple algorithm support,Automated model training,A/B testing capabilities,Model versioning,Performance monitoring,Auto-scaling deployment, Improved prediction accuracy,Automated model updates,Scalable infrastructure,Reduced development time, Demand forecasting,Fraud detection,Recommendation systems,Quality control, 'Starting at $599/month', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=600&h=400&fit=crop&crop=center', 'Brain', 'published', false, 4, '2025-09-27 04:00:53.098429+00', '2025-09-27 04:00:53.098429+00');
